// O que o event source mapping entrega ao consumidor .NET, um registro do
// lote (DynamoDBEvent.Records[i]). NewImage e OldImage vêm no formato de tipo
// do DynamoDB (wrapper {"S": ...}, {"N": ...}), não em JSON "normal".
{
  "eventID": "8f105b654fb0c2c4e6a6f6b0f1a2b3c4",
  "eventName": "MODIFY",
  "eventSource": "aws:dynamodb",
  "awsRegion": "us-east-1",
  "dynamodb": {
    "ApproximateCreationDateTime": 1754571801,
    "Keys": {
      "PK": { "S": "PEDIDO#b7a1f0b0-2c44-4e9a-9d31-000000009182" },
      "SK": { "S": "METADADOS" }
    },
    "OldImage": {
      "status": { "S": "PENDENTE" },
      "GSI3PK": { "S": "LOJA#a10ecb4e-6f21-4a02-8b9d-000000000512" },
      "GSI3SK": { "S": "2026-08-07T14:03:21Z" }
    },
    "NewImage": {
      "status": { "S": "SEPARADO" }
      // GSI3PK/GSI3SK ausentes: o L16 já os removia ao separar — o item some
      // da fila de pendentes, e essa ausência também está retratada aqui.
    },
    // A ordem DENTRO desta partição (este pedido) é garantida pelo número de
    // sequência crescente. Entre pedidos de partições diferentes, não é.
    "SequenceNumber": "400000000000000499659",
    "SizeBytes": 287,
    "StreamViewType": "NEW_AND_OLD_IMAGES"
  },
  "eventSourceARN": "arn:aws:dynamodb:us-east-1:111122223333:table/pedidos_cadencia/stream/2026-08-07T00:00:00.000"
}

# tabela.tf — o stream é um ATRIBUTO da tabela do L16, não uma tabela nova

resource "aws_dynamodb_table" "pedidos" {
  name         = "pedidos_cadencia"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute { name = "PK" type = "S" }
  attribute { name = "SK" type = "S" }
  # ... GSI1/GSI2/GSI3 continuam como no L16; omitidos aqui por brevidade.

  # As duas linhas que este laboratório acrescenta à tabela do L16.
  # NEW_AND_OLD_IMAGES e nao NEW_IMAGE: sem a imagem antiga, o consumidor
  # nunca saberia que um pedido "cancelado" tinha passado por "separado" —
  # e essa comparacao e o motivo deste laboratorio existir.
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  point_in_time_recovery {
    enabled = true
  }
}

output "stream_arn" {
  value       = aws_dynamodb_table.pedidos.stream_arn
  description = "ARN do stream; muda se a tabela for recriada — o consumidor referencia este output, nunca uma string fixa"
}

# painel.tf — o log de transicoes, e o alerta que passa a ter informacao para existir

resource "aws_dynamodb_table" "painel_operacao" {
  name         = "painel_operacao"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  # PK = PEDIDO#<id> igual a tabela de origem, para o gerente nao precisar
  # aprender uma segunda convencao de chave.
  # SK = "ATUAL"                    -> o estado mais recente conhecido
  # SK = "TRANSICAO#<SequenceNumber>" -> uma linha por mudanca, append-only
  attribute { name = "PK" type = "S" }
  attribute { name = "SK" type = "S" }

  tags = { Projeto = "ffv-lab", Papel = "read-model-operacional" }
}

resource "aws_sns_topic" "alerta_estoque" {
  name = "ffv-lab-alerta-reposicao-estoque"
}

resource "aws_sqs_queue" "dlq_stream" {
  name                      = "ffv-lab-consumidor-pedidos-dlq"
  message_retention_seconds = 1209600 # 14 dias — tempo para alguem investigar antes de expirar
}

# consumidor.tf — o Lambda que ouve o stream, e o event source mapping que o alimenta

data "aws_iam_policy_document" "consumidor_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "consumidor" {
  name               = "ffv-lab-consumidor-pedidos"
  assume_role_policy = data.aws_iam_policy_document.consumidor_assume.json
}

data "aws_iam_policy_document" "consumidor_permissoes" {
  # Ler o stream. As tres primeiras aceitam o ARN especifico do stream; a
  # quarta e operacao de DESCOBERTA DE CONTA e nao aceita recurso — mesma
  # justificativa do ecr:GetAuthorizationToken no L03.
  statement {
    effect = "Allow"
    actions = [
      "dynamodb:DescribeStream",
      "dynamodb:GetRecords",
      "dynamodb:GetShardIterator",
    ]
    resources = ["${aws_dynamodb_table.pedidos.stream_arn}"]
  }
  statement {
    effect    = "Allow"
    actions   = ["dynamodb:ListStreams"]
    resources = ["*"] # ListStreams e por conta/regiao; nao existe ARN de stream para restringir
  }
  statement {
    effect    = "Allow"
    actions   = ["dynamodb:PutItem"]
    resources = [aws_dynamodb_table.painel_operacao.arn]
  }
  statement {
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.alerta_estoque.arn]
  }
  # O event source mapping usa o papel DA FUNCAO para escrever na DLQ quando
  # descarta um lote — por isso a permissao mora aqui, nao num papel separado.
  statement {
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.dlq_stream.arn]
  }
}

resource "aws_iam_role_policy" "consumidor" {
  role   = aws_iam_role.consumidor.id
  policy = data.aws_iam_policy_document.consumidor_permissoes.json
}

resource "aws_lambda_function" "consumidor" {
  function_name = "ffv-lab-consumidor-pedidos"
  role          = aws_iam_role.consumidor.arn
  runtime       = "dotnet8"
  handler       = "Consumidor::Consumidor.Function::HandlerAsync"
  filename      = "consumidor.zip"
  timeout       = 30
  memory_size   = 256

  environment {
    variables = {
      TABELA_PAINEL   = aws_dynamodb_table.painel_operacao.name
      TOPICO_ESTOQUE  = aws_sns_topic.alerta_estoque.arn
    }
  }
}

resource "aws_lambda_event_source_mapping" "stream_pedidos" {
  event_source_arn  = aws_dynamodb_table.pedidos.stream_arn
  function_name     = aws_lambda_function.consumidor.arn
  starting_position = "LATEST" # so o que acontecer DAQUI PRA FRENTE; ver callout sobre TRIM_HORIZON

  batch_size                        = 100 # padrao do stream do DynamoDB; maximo 10000
  maximum_batching_window_in_seconds = 1   # nao espera lote encher; prioriza latencia sobre eficiencia

  # Falha isolada nao trava a particao inteira: divide o lote ao meio e tenta
  # de novo cada metade separadamente, ate achar o registro problematico.
  bisect_batch_on_function_error = true
  maximum_retry_attempts         = 3 # finito, de proposito — ver callout sobre o padrao ser infinito

  # Permite ao consumidor reportar QUAIS registros do lote falharam, em vez de
  # o lote inteiro ser tratado como falha ou sucesso.
  function_response_types = ["ReportBatchItemFailures"]

  destination_config {
    on_failure {
      destination_arn = aws_sqs_queue.dlq_stream.arn
    }
  }
}

resource "aws_cloudwatch_metric_alarm" "atraso_do_consumidor" {
  alarm_name          = "ffv-lab-consumidor-pedidos-iterator-age"
  namespace           = "AWS/Lambda"
  metric_name         = "IteratorAge"
  statistic           = "Maximum"
  period              = 60
  evaluation_periods  = 3
  threshold           = 60000 # 60 s em milissegundos — bem acima do que a operacao normal produz
  comparison_operator = "GreaterThanThreshold"
  treat_missing_data  = "notBreaching"

  dimensions = {
    FunctionName = aws_lambda_function.consumidor.function_name
  }

  alarm_actions = [aws_sns_topic.alerta_estoque.arn] # reaproveitado para alerta operacional
}

// Function.cs — compara antes e depois, grava a transicao, publica o alerta
// que o polling nunca conseguia disparar.

using Amazon.DynamoDBv2;
using Amazon.DynamoDBv2.Model;
using Amazon.Lambda.Core;
using Amazon.Lambda.DynamoDBEvents;
using Amazon.SimpleNotificationService;
using Amazon.SimpleNotificationService.Model;

namespace Consumidor;

public class Function
{
    private readonly IAmazonDynamoDB _dynamo = new AmazonDynamoDBClient();
    private readonly IAmazonSimpleNotificationService _sns = new AmazonSimpleNotificationServiceClient();
    private readonly string _tabelaPainel = Environment.GetEnvironmentVariable("TABELA_PAINEL")!;
    private readonly string _topicoEstoque = Environment.GetEnvironmentVariable("TOPICO_ESTOQUE")!;

    // Retorna DynamoDBBatchResponse com os itens que falharam, para o event
    // source mapping reprocessar SO ESSES — e nao o lote inteiro. Sem isso,
    // um unico registro com formato inesperado faria o lote inteiro repetir,
    // inclusive os que ja tinham sido gravados com sucesso.
    public async Task<DynamoDBBatchResponse> HandlerAsync(DynamoDBEvent evento, ILambdaContext contexto)
    {
        var falhas = new List<DynamoDBBatchResponse.BatchItemFailure>();

        foreach (var registro in evento.Records)
        {
            try
            {
                await ProcessarAsync(registro, contexto);
            }
            catch (Exception ex)
            {
                contexto.Logger.LogError($"Falha no registro {registro.Dynamodb.SequenceNumber}: {ex.Message}");
                // O identificador tem de ser o SequenceNumber: e a chave que o
                // event source mapping usa para saber ONDE retomar.
                falhas.Add(new DynamoDBBatchResponse.BatchItemFailure
                {
                    ItemIdentifier = registro.Dynamodb.SequenceNumber
                });
            }
        }

        return new DynamoDBBatchResponse { BatchItemFailures = falhas };
    }

    private async Task ProcessarAsync(DynamoDBEvent.DynamodbStreamRecord registro, ILambdaContext contexto)
    {
        // INSERT e pedido novo; REMOVE e exclusao fisica. So MODIFY carrega
        // uma transicao de status, que e o que este laboratorio trata.
        if (registro.EventName != "MODIFY") return;

        var pedidoId = registro.Dynamodb.Keys["PK"].S;
        var statusAntigo = registro.Dynamodb.OldImage.TryGetValue("status", out var oldAttr) ? oldAttr.S : null;
        var statusNovo = registro.Dynamodb.NewImage.TryGetValue("status", out var newAttr) ? newAttr.S : null;

        if (statusAntigo == statusNovo) return; // mudou outro atributo; nao e transicao de status

        // Chave deterministica a partir do SequenceNumber: reprocessar o MESMO
        // registro do stream (entrega e pelo menos uma vez) grava o MESMO
        // item, em vez de duplicar a transicao no painel.
        var itemTransicao = new Dictionary<string, AttributeValue>
        {
            ["PK"] = new AttributeValue { S = pedidoId },
            ["SK"] = new AttributeValue { S = $"TRANSICAO#{registro.Dynamodb.SequenceNumber}" },
            ["de"] = new AttributeValue { S = statusAntigo ?? "INEXISTENTE" },
            ["para"] = new AttributeValue { S = statusNovo ?? "DESCONHECIDO" },
            ["em"] = new AttributeValue { S = DateTimeOffset.UtcNow.ToString("O") },
        };
        await _dynamo.PutItemAsync(_tabelaPainel, itemTransicao);

        // O item ATUAL e sobrescrito de proposito — e o unico que representa
        // "agora", e nao precisa de historico.
        var itemAtual = new Dictionary<string, AttributeValue>
        {
            ["PK"] = new AttributeValue { S = pedidoId },
            ["SK"] = new AttributeValue { S = "ATUAL" },
            ["status"] = new AttributeValue { S = statusNovo ?? "DESCONHECIDO" },
            ["atualizadoEm"] = new AttributeValue { S = DateTimeOffset.UtcNow.ToString("O") },
        };
        await _dynamo.PutItemAsync(_tabelaPainel, itemAtual);

        // A regra que o polling nunca conseguia avaliar: exige o ANTES e o
        // DEPOIS no MESMO registro, e so o stream entrega os dois juntos.
        if (statusAntigo == "SEPARADO" && statusNovo == "CANCELADO")
        {
            await _sns.PublishAsync(new PublishRequest
            {
                TopicArn = _topicoEstoque,
                Subject = "Pedido cancelado apos separado — reposicao de estoque",
                Message = $"Pedido {pedidoId} foi cancelado depois de ja estar separado. " +
                          "O item embalado precisa voltar ao estoque fisico."
            });
        }
    }
}
